from collections.abc import Iterable, Mapping


def dependency_batches(tasks: Mapping[str, Iterable[str]]) -> list[list[str]]:
    if any(not isinstance(task, str) or not task for task in tasks):
        raise ValueError("task identifiers must be non-empty strings")
    dependencies: dict[str, set[str]] = {}
    for task, items in tasks.items():
        if isinstance(items, (str, bytes)):
            raise ValueError("task identifiers must be non-empty strings")
        try:
            iterator = iter(items)
        except TypeError:
            raise ValueError("task identifiers must be non-empty strings") from None
        normalized: set[str] = set()
        for dependency in iterator:
            if not isinstance(dependency, str) or not dependency:
                raise ValueError("task identifiers must be non-empty strings")
            normalized.add(dependency)
        dependencies[task] = normalized

    missing = sorted(
        (task, dependency)
        for task, items in dependencies.items()
        for dependency in items
        if dependency not in dependencies
    )
    if missing:
        task, dependency = missing[0]
        raise ValueError(f"missing dependency: {task} -> {dependency}")

    remaining = set(dependencies)
    batches: list[list[str]] = []
    while remaining:
        batch = sorted(
            task for task in remaining if dependencies[task].isdisjoint(remaining)
        )
        if not batch:
            raise ValueError("dependency cycle")
        batches.append(batch)
        remaining.difference_update(batch)
    return batches
